Section Loop.
Context {AC : AllocCeiling} {RRND : RunRandom}.
  Context {AMB : Amb}.
  Variable MI : MallocIface SEGS L.
  Hypothesis DMc : mi_constsG MI.
  Variables (sp0 tid : Z) (content : list byte) (fs0 : Fs) (p cap : Z) (R0 : bvmap 5 word).
  Hypothesis Hsp : 0x7fff80000000 <= sp0 <= 0x800000000000 /\ sp0 mod 16 = 0.
  Hypothesis HAC : alloc_ceiling = sp0 - 8388608.
  Hypothesis Hcap : 0x124000 <= p /\ p + cap <= alloc_ceiling /\ 65536 <= cap <= 2 ^ 26.
  Hypothesis HL6 : 6 + hdr_cfglen content <= Z.of_nat (length content) < 2 ^ 26.
  Hypothesis Htid : 1 <= tid < 2 ^ 22.
  Hypothesis R0_9 : getr R0 9 = Z_to_bv 64 p.

  #[local] Abbreviation TCORE := (tcore MI sp0 tid content fs0 p cap R0).
  #[local] Abbreviation TREGS := (tregs sp0 content).
  #[local] Abbreviation TN := (tn content).

  Let KX : TSet := t_exit (exit_code 0) fs0.

  Lemma exit_k : forall (fx : FPState) k A R M model,
    tmem sp0 tid k 0 M -> tabs MI A M model -> sx_inv U1ST true M -> m_fs model = fs0 ->
    getr R 2 = Z_to_bv 64 (sp0 - 48) -> getr R 4 = Z_to_bv 64 0x102418 -> getr R 10 = Z_to_bv 64 0 ->
    (1 <= k <= 4)%nat ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 EXITPC) M (seg_rom RSEGS)) model)
              (t_emit (W 1 (zero_lines (k - 1))) KX).
