  Lemma fin_tail : forall (fx : FPState) k A R M model (v1 v2 v3 v4 v5 : Z),
    tmem sp0 tid k 0 M -> tabs MI A M model -> sx_inv U1ST true M -> tr_frame sp0 R0 M -> main_frame sp0 M ->
    In (p, cap) (live MI A) -> m_fs model = fs0 ->
    getr R 2 = Z_to_bv 64 (sp0 - 208) -> getr R 3 = Z_to_bv 64 0x10800 -> getr R 4 = Z_to_bv 64 0x102418 ->
    getr R 8 = Z_to_bv 64 v1 -> getr R 9 = Z_to_bv 64 v2 -> getr R 18 = Z_to_bv 64 v3 -> getr R 19 = Z_to_bv 64 v4 ->
    getr R 20 = Z_to_bv 64 INITIALIZED -> getr R 21 = Z_to_bv 64 v5 -> getr R 22 = Z_to_bv 64 0 -> getr R 23 = Z_to_bv 64 MINUS2 ->
    0 <= v4 < 2 ^ 64 -> 0 <= v5 <= 4 -> (1 <= k <= 4)%nat ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 RET_FREE) M (seg_rom RSEGS)) model)
